-- 本场覆盖九局上下半：曹魏在一、四、六局得分，蜀汉在三、五、九局反攻，并在九局下半以两支阳春本垒打完成 5:4 逆转。
WITH half_innings AS (
    SELECT inning, half, runs
    FROM (VALUES
        (1, 1, 1), (1, 2, 0), (2, 1, 0), (2, 2, 0),
        (3, 1, 0), (3, 2, 1), (4, 1, 2), (4, 2, 0),
        (5, 1, 0), (5, 2, 2), (6, 1, 1), (6, 2, 0),
        (7, 1, 0), (7, 2, 0), (8, 1, 0), (8, 2, 0),
        (9, 1, 0), (9, 2, 2)
    ) AS fixture(inning, half, runs)
),
plate_appearances AS (
    SELECT
        ROW_NUMBER() OVER (ORDER BY inning, half, plate) AS sequence,
        inning, half, plate, runs,
        plate <= runs AS scored
    FROM half_innings
    CROSS JOIN LATERAL generate_series(1, 3 + runs) AS plate
),
play_rows AS (
    SELECT
        sequence, inning, half, plate, scored,
        COALESCE(SUM(CASE WHEN half = 2 AND scored THEN 1 ELSE 0 END) OVER (ORDER BY sequence ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0)::int AS home_before,
        COALESCE(SUM(CASE WHEN half = 1 AND scored THEN 1 ELSE 0 END) OVER (ORDER BY sequence ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0)::int AS away_before,
        GREATEST(plate - runs - 1, 0) AS before_outs,
        GREATEST(plate - runs, 0) AS after_outs,
        CASE WHEN half = 2
            THEN (ARRAY['00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000013','00000000-0000-0000-0000-000000000014','00000000-0000-0000-0000-000000000015','00000000-0000-0000-0000-000000000016','00000000-0000-0000-0000-000000000017','00000000-0000-0000-0000-000000000018','00000000-0000-0000-0000-000000000019','00000000-0000-0000-0000-000000000012'])[(sequence - 1) % 9 + 1]
            ELSE (ARRAY['00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000033','00000000-0000-0000-0000-000000000034','00000000-0000-0000-0000-000000000035','00000000-0000-0000-0000-000000000036','00000000-0000-0000-0000-000000000037','00000000-0000-0000-0000-000000000038','00000000-0000-0000-0000-000000000039','00000000-0000-0000-0000-000000000032'])[(sequence - 1) % 9 + 1]
        END AS batter_id,
        CASE WHEN half = 2 THEN '00000000-0000-0000-0000-000000000032' ELSE '00000000-0000-0000-0000-000000000012' END AS pitcher_id
    FROM plate_appearances
)
INSERT INTO plays(
    id, match_id, sequence, inning, half, batting_order, batter_id, starting_pitcher_id,
    batting_result, result_description, before_outs, before_home_score, before_away_score,
    before_runner_on_first_id, before_runner_on_second_id, before_runner_on_third_id,
    after_outs, after_home_score, after_away_score,
    after_runner_on_first_id, after_runner_on_second_id, after_runner_on_third_id, created_at, updated_at
)
SELECT
    ('00000000-0000-0000-0000-' || lpad((400 + sequence)::text, 12, '0'))::uuid,
    '00000000-0000-0000-0000-000000000201', sequence, inning, half, ((sequence - 1) % 9) + 1,
    batter_id::uuid, pitcher_id::uuid,
    CASE WHEN scored THEN 4 ELSE 8 END,
    CASE WHEN scored THEN '击出阳春本垒打得分' ELSE '挥棒落空三振出局' END,
    before_outs, home_before, away_before, NULL, NULL, NULL,
    after_outs,
    home_before + CASE WHEN half = 2 AND scored THEN 1 ELSE 0 END,
    away_before + CASE WHEN half = 1 AND scored THEN 1 ELSE 0 END,
    NULL, NULL, NULL, now(), now()
FROM play_rows;

INSERT INTO play_pitching_results(
    id, play_id, sequence, pitcher_id, batter_id, result,
    balls_before, strikes_before, balls_after, strikes_after,
    pitch_type, velocity, zone, description, created_at, updated_at
)
SELECT
    ('00000000-0000-0000-0000-' || lpad((500 + sequence)::text, 12, '0'))::uuid,
    id, 1, starting_pitcher_id, batter_id,
    CASE WHEN batting_result = 4 THEN 6 ELSE 2 END,
    0, 0, 0, CASE WHEN batting_result = 4 THEN 0 ELSE 1 END,
    CASE WHEN batting_result = 4 THEN '四缝线快球' ELSE '滑球' END,
    CASE WHEN batting_result = 4 THEN 146.2 ELSE 132.4 END,
    CASE WHEN batting_result = 4 THEN 5 ELSE 7 END,
    CASE WHEN batting_result = 4 THEN '击球越过外野全垒打墙' ELSE '挥棒落空三振' END,
    now(), now()
FROM plays
WHERE match_id = '00000000-0000-0000-0000-000000000201';

INSERT INTO play_runner_results(
    id, play_id, sequence, runner_id, result, from_base, to_base,
    out_recorded, scored, charged_pitcher_id, earned, rbi_batter_id,
    description, created_at, updated_at
)
SELECT
    ('00000000-0000-0000-0000-' || lpad((600 + sequence)::text, 12, '0'))::uuid,
    id, 1, batter_id, 2, 0, 4, FALSE, TRUE,
    starting_pitcher_id, TRUE, batter_id,
    '击出阳春本垒打返回本垒得分', now(), now()
FROM plays
WHERE match_id = '00000000-0000-0000-0000-000000000201'
  AND batting_result = 4;
